#!/usr/bin/env python3
"""Export only byte-identical whitelisted records generated by this owned performance run."""
import argparse
import collections
import hashlib
import json
from pathlib import Path
import shutil

HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[2]
SOURCE_SHA='c892bff3a0148e78727d257acc8bb381258b6b01c3f6dcfb9b4888a0aac22ae4'
ORIGINS={
    'memory.json':'gm_save/gm_make_source/core_add_source -> core_commit_memory',
    'memory.backup.json':'gm_save/gm_make_source/core_add_source -> core_commit_memory',
    'goals.json':'core_add_goal/core_start_run/core_begin_action -> core_commit_goals',
    'goals.backup.json':'core_add_goal/core_start_run/core_begin_action -> core_commit_goals',
    'activity.json':'gm_save queued audit -> core_record_event',
    'activity.backup.json':'gm_save queued audit -> core_record_event',
    'global-memory-settings.json':'gm_boot generated synthetic user identity in owned state',
    'memory-retrieval-last.json':'gm_context/gm_context_ranked -> storage_write audit',
    'chat-sessions.json':'chat_save (only export if actually persisted)',
    'chat-sessions.backup.json':'chat_save (only export if actually persisted)',
}
sha=lambda data:hashlib.sha256(data).hexdigest()
write_json=lambda path,data:path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')

def scope_counts(records,fields=('project','account','visibility','user_id','project_id','owner_id')):
    counts=collections.Counter(tuple(record.get(key,'') for key in fields) for record in records)
    return [dict(zip(fields,key),records=count) for key,count in sorted(counts.items())]

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--run',type=Path,required=True)
    parser.add_argument('--source-sha',default=SOURCE_SHA)
    parser.add_argument('--out',type=Path,required=True)
    args=parser.parse_args()
    run=args.run.resolve();run.relative_to(ROOT/'build')
    state=run/'main-state'
    assert (state/'FIXTURE_ONLY').read_text()=='NIGHT004 performance fixture only\n'
    report=json.loads((run/'report.json').read_text())
    assert report['status']=='PASS' and report['source_sha256']==args.source_sha
    load=lambda name:json.loads((state/name).read_text())
    memory=load('memory.json');goals=load('goals.json');activity=load('activity.json');settings=load('global-memory-settings.json')
    assert len(memory['claims'])==64 and len(memory['sources'])==128 and not memory['forget']
    assert len(goals['goals'])==len(goals['runs'])==32 and len(goals['actions'])==128
    assert all(goal['status']=='running' for goal in goals['goals'])
    assert all(run['status']=='running' for run in goals['runs'])
    assert all(action['status']=='in_flight' and action['payload_json']=='{"fixture":true}' for action in goals['actions'])
    values={'规模条目 '+('LOCAL_' if index<48 else 'FOREIGN_PROJECT_' if index<56 else 'FOREIGN_OWNER_')+str(index)+' · 合成安排资料，不授权操作。' for index in range(64)}
    assert {entry['document']['payload']['value'] for entry in memory['claims']}==values
    assert all(entry['document']['payload']['epistemic_type']=='user_statement' for entry in memory['claims'])
    excerpts=values|{'合法孤立来源 '+str(index) for index in range(64)}
    assert {source['support_excerpt'] for source in memory['sources']}==excerpts
    assert all(source['kind']=='user' and source['locator']=='conversation:scale-chat' for source in memory['sources'])
    assert settings['user_id']=='user:profile:1-2-3-4' and set(settings)=={'schema','enabled','forget_pending','user_id'}
    assert all(item['kind']=='memory saved' for item in activity)
    assert all(goal['goal']=='Fixture Goal '+goal['id'] and goal['source']=='Fixture source '+goal['id']
        and not goal['model_summary'] and not goal['items'] for goal in goals['goals'])
    out=args.out.resolve();out.relative_to(ROOT/'build');out.mkdir(parents=True,exist_ok=False)
    files=out/'fixture_files';files.mkdir()
    provenance=[];absent=[]
    for name,origin in ORIGINS.items():
        source=state/name
        if not source.exists():absent.append(name);continue
        assert source.resolve().parent==state and sha(source.read_bytes())==report['state_sha256'][name]
        data=load(name)
        if name in ('memory.json','memory.backup.json'):
            assert all(entry['document']['payload']['value'] in values and entry['document']['payload']['epistemic_type']=='user_statement' for entry in data['claims'])
            records=dict(memory=len(data['claims']),sources=len(data['sources']),forget=len(data['forget']))
        elif name in ('goals.json','goals.backup.json'):
            assert all(item['status']=='running' for item in data['goals']+data['runs']) and all(item['status']=='in_flight' for item in data['actions'])
            records={key:len(data[key]) for key in ('goals','runs','actions')}
        elif name in ('activity.json','activity.backup.json'):
            assert all(item['kind']=='memory saved' for item in data)
            records=dict(activity=len(data))
        elif name=='memory-retrieval-last.json':records=dict(hits=len(data['hits']),bytes=data['bytes'])
        else:records=dict(settings=1)
        shutil.copy2(source,files/name)
        assert source.read_bytes()==(files/name).read_bytes()
        provenance.append(dict(file=name,bytes=source.stat().st_size,sha256=sha(source.read_bytes()),generated_by=origin,records=records,
            source_path=str(source),source_run_report_sha256=sha((run/'report.json').read_bytes()),byte_identical=True))
    assert 'chat-sessions.json' in absent and 'chat-sessions.backup.json' in absent
    scopes=dict(current_fixture_scope=dict(user_id=settings['user_id'],project='muse-goals',visibility='personal',project_id='fixture-project',owner_id='fixture-owner',accounts=['local']),
        memory=scope_counts([entry['document']['scope'] for entry in memory['claims']]),
        sources=scope_counts([source['scope'] for source in memory['sources']]),
        goals=scope_counts(goals['goals'],('project_id','owner_id')),action_target_scopes=dict(collections.Counter(action['target_scope'] for action in goals['actions'])),
        boundary='Synthetic gm_boot identity and gm_set_focus fields; not Root profile or Host default scope. No scope rewriting performed.')
    write_json(out/'scope.json',scopes)
    manifest=dict(status='PASS',source_sha256=args.source_sha,source_run=str(run),source_run_report_sha256=sha((run/'report.json').read_bytes()),exporter_sha256=sha(Path(__file__).read_bytes()),
        counts=dict(memory=64,sources=128,goals=32,runs=32,actions=128,activity=len(activity)),
        statuses=dict(goals=dict(collections.Counter(goal['status'] for goal in goals['goals'])),
            runs=dict(collections.Counter(run['status'] for run in goals['runs'])),actions=dict(collections.Counter(action['status'] for action in goals['actions']))),
        completed_records=0,verified_records=0,synthetic_literal_text_only=True,private_profile_or_credentials_read=False,
        files=provenance,absent_whitelist_files=absent,scope_sha256=sha((out/'scope.json').read_bytes()),
        gui_import_status='NOT_TESTED',boundary='Byte-identical allowlisted output of actual benchmark production save APIs. Chat was only a runtime view fixture and never chat_save persisted, so no chat file fabricated. Root decides legitimate SDK storage location/default-scope adaptation; no UI state or profile edited.')
    write_json(out/'manifest.json',manifest)
    (out/'FIXTURE_ONLY').write_text('NIGHT004 owned synthetic scale export; not a production profile\n')
    print(json.dumps(dict(status=manifest['status'],files=len(provenance),counts=manifest['counts'],completed_records=0,verified_records=0,
        absent=absent,gui_import_status='NOT_TESTED'),ensure_ascii=False))

if __name__=='__main__':main()
